<script setup>
import { ref,onMounted } from 'vue'; import { RouterLink } from 'vue-router'; import { api } from '../lib/api'; import { state } from '../lib/state'; import { num,pct,date,obraPath } from '../lib/format'; import StatTile from '../components/StatTile.vue'; import PageCard from '../components/PageCard.vue';
const data=ref(null),loading=ref(true),error=ref('');
onMounted(async()=>{try{data.value=await api.get('/dashboard')}catch(e){error.value=e.message}finally{loading.value=false}});
</script>
<template><div class="page-heading"><div class="page-heading__titles"><div class="eyebrow">Panel general</div><h1 class="page-title display">Hola, {{state.user?.name?.split(' ')[0]}}</h1><p class="page-description">Control y seguimiento de obras</p></div></div>
<p v-if="error" class="notice bad" role="alert">{{error}}</p><p v-else-if="loading">Cargando resumen…</p><template v-else-if="data"><div class="stat-grid cols-4 dashboard-stats"><StatTile label="Avance medio de obras" :value="pct(data.average_progress)" hint="Real, curva principal de cada obra" focal/><StatTile label="Personas en obra" :value="num(data.staff)" hint="Tocal y subcontratos, última semana"/><StatTile label="Consultas sin responder" :value="num(data.pending)" hint="RDI pendientes del mandante" :tone="data.pending>5?'warn':'ok'"/><StatTile label="Accidentes acumulados" :value="num(data.accidents)" hint="Suma de todas tus obras" :tone="data.accidents?'bad':'ok'"/></div>
<PageCard v-if="data.sales" :title="`Ventas ${data.year}`" description="Facturación neta del año"><template #actions><RouterLink to="/ventas" class="btn btn-sm">Ver ventas →</RouterLink></template><div class="sales-strip"><div class="sales-strip__figure"><div class="sales-strip__value display">UF {{num(data.sales?.total?.uf)}}</div><p class="sales-strip__meta">{{num(data.sales?.total?.clp)}} CLP · {{data.sales?.documents}} documentos</p></div></div></PageCard>
<div class="section-head"><h2 class="section-head__title">Mis obras</h2><span class="section-head__count">{{data.cards?.length||0}} obras</span></div>
<div class="obra-grid" style="display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:18px"><RouterLink v-for="c in data.cards" :key="c.obra.id" :to="obraPath(c.obra.id)" class="card obra-card" style="padding:22px;text-decoration:none"><div class="card__head"><p class="eyebrow">{{c.obra.activa?'En ejecución':'Finalizada'}}</p><h3 class="card__title">{{c.obra.nombre}}</h3></div><p class="muted">{{c.obra.servicio}}</p><div class="stat-grid cols-2"><StatTile label="Avance real" :value="pct(c.state?.real)"/><StatTile label="Variación" :value="pct(c.state?.variacion)" :tone="c.progress_tone"/></div><div class="muted" style="margin-top:15px">PDR: {{num(c.pdr,1)}} % · RDI pendientes: {{c.pending}}</div><p class="btn btn-sm" style="margin-top:12px">Abrir obra →</p></RouterLink></div>
<p v-if="!data.cards?.length" class="notice">No tienes obras asignadas todavía.</p></template></template>
